 private String localHost(String value)throws Exception{String h=value.trim().replaceFirst("^https?://","").replaceFirst(":878[79]/?$","").replaceFirst("/$","");if(!h.matches("[0-9.]+"))throw new Exception("Нужен локальный IPv4-адрес");InetAddress ip=InetAddress.getByName(h);if(!(ip instanceof Inet4Address)||!ip.isSiteLocalAddress())throw new Exception("Нужен адрес в домашней сети");return ip.getHostAddress();}
 private static String hex(byte[] data){StringBuilder b=new StringBuilder();for(byte v:data)b.append(String.format(Locale.US,"%02x",v&255));return b.toString();}
 private static String nonce(){byte[] b=new byte[16];new SecureRandom().nextBytes(b);return hex(b);}
 private static String mac(String code,String data)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(code.getBytes("US-ASCII"),"HmacSHA256"));return hex(m.doFinal(data.getBytes("UTF-8")));}
 private final class PinnedTrust implements X509TrustManager {private final String expected;String observed;PinnedTrust(String expected){this.expected=expected;}public void checkClientTrusted(X509Certificate[]c,String a)throws CertificateException{throw new CertificateException();}public void checkServerTrusted(X509Certificate[]c,String a)throws CertificateException{try{if(c==null||c.length==0)throw new Exception();c[0].checkValidity();observed=hex(MessageDigest.getInstance("SHA-256").digest(c[0].getEncoded()));if(expected!=null&&!MessageDigest.isEqual(observed.getBytes("US-ASCII"),expected.getBytes("US-ASCII")))throw new Exception();}catch(Exception e){throw new CertificateException("Сертификат станции изменился");}}public X509Certificate[]getAcceptedIssuers(){return new X509Certificate[0];}}
 private HttpsURLConnection connection(String target,String path,PinnedTrust trust)throws Exception{String safe=localHost(target);SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,new TrustManager[]{trust},new SecureRandom());HttpsURLConnection c=(HttpsURLConnection)new URL("https://"+safe+":8789"+path).openConnection();c.setSSLSocketFactory(ssl.getSocketFactory());c.setHostnameVerifier((hostname,session)->hostname.equals(safe));c.setConnectTimeout(4000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);return c;}
 private byte[] readBounded(InputStream in,int limit)throws Exception{try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=stream.read(b))!=-1){out.write(b,0,n);if(out.size()>limit)throw new IOException("Слишком большой ответ");}return out.toByteArray();}}
 private JSONObject request(String path,JSONObject body)throws Exception{HttpsURLConnection c=connection(host,path,new PinnedTrust(pin));try{c.setRequestProperty("Authorization","Bearer "+key);if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();JSONObject j=new JSONObject(new String(readBounded(code<400?c.getInputStream():c.getErrorStream(),262144),"UTF-8"));if(code>=400)throw new Exception(j.optString("error","Станция отклонила запрос"));return j;}finally{c.disconnect();}}
 private void introductory(String title,String text){if(topBar!=null)topBar.setVisibility(View.VISIBLE);if(web!=null){web.destroy();web=null;}content.removeAllViews();LinearLayout page=new LinearLayout(this);page.setPadding(dp(24),dp(35),dp(24),dp(24));page.setOrientation(1);android.widget.ImageView emblem=new android.widget.ImageView(this);emblem.setImageResource(getResources().getIdentifier("studio_icon","drawable",getPackageName()));LinearLayout.LayoutParams emblemSize=new LinearLayout.LayoutParams(dp(72),dp(72));emblemSize.bottomMargin=dp(24);page.addView(emblem,emblemSize);page.addView(label(title,27,0xff28232f));TextView detail=label(text,15,0xff8c829b);detail.setPadding(0,dp(18),0,dp(20));detail.setLineSpacing(dp(4),1);page.addView(detail);ScrollView scroll=new ScrollView(this);scroll.addView(page);content.addView(scroll,new LinearLayout.LayoutParams(-1,-1));content.setTag(page);}
 private void discover(){final int ticket=discoveryGeneration.incrementAndGet();connected=false;introductory("Подключение к станции","Телефон и станция должны быть в одной сети Wi-Fi. Первое подключение подтверждается кодом на станции.");LinearLayout page=(LinearLayout)content.getTag();page.addView(button("Указать адрес",()->manualAddress()));page.addView(button("Панель ещё не установлена",()->setupHelp()));status.setText("Поиск станций…");found.clear();new Thread(()->{try(DatagramSocket socket=new DatagramSocket()){socket.setBroadcast(true);socket.setSoTimeout(550);byte[] query=("STATION_STUDIO_DISCOVER_V1:"+nonce()).getBytes("US-ASCII");Set<String> broadcasts=new HashSet<>();broadcasts.add("255.255.255.255");Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();while(interfaces.hasMoreElements())for(InterfaceAddress a:interfaces.nextElement().getInterfaceAddresses())if(a.getBroadcast()!=null&&a.getAddress().isSiteLocalAddress())broadcasts.add(a.getBroadcast().getHostAddress());long until=System.currentTimeMillis()+4500;while(System.currentTimeMillis()<until&&!destroyed&&ticket==discoveryGeneration.get()){for(String address:broadcasts)socket.send(new DatagramPacket(query,query.length,InetAddress.getByName(address),8788));try{byte[] data=new byte[4096];DatagramPacket packet=new DatagramPacket(data,data.length);socket.receive(packet);JSONObject j=new JSONObject(new String(data,0,packet.getLength(),"UTF-8"));String candidate=localHost(packet.getAddress().getHostAddress());if(j.optInt("version")>=2&&j.optInt("tlsPort")==8789&&j.optBoolean("pairing")&&found.add(candidate))runOnUiThread(()->{if(!destroyed&&ticket==discoveryGeneration.get())page.addView(button("Station Max · "+candidate,()->pair(candidate)));});}catch(SocketTimeoutException ignored){}}}catch(Exception e){message("Поиск недоступен. Можно указать адрес станции.");}runOnUiThread(()->status.setText(found.isEmpty()?"Станция не найдена":"Выберите станцию"));},"station-discovery").start();}
 private void manualAddress(){EditText input=new EditText(this);input.setSingleLine();input.setHint("192.168.1.100");new AlertDialog.Builder(this).setTitle("Адрес станции").setView(input).setPositiveButton("Подключить",(d,w)->{try{pair(localHost(input.getText().toString()));}catch(Exception e){message(e.getMessage());}}).setNegativeButton("Отмена",null).show();}
