 private void pair(String target){EditText code=new EditText(this);code.setSingleLine();code.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);code.setHint("Код из панели станции");new AlertDialog.Builder(this).setTitle("Подключить телефон").setMessage("На станции: Система → Подключить телефон. Введите показанный код.").setView(code).setPositiveButton("Подключить",(d,w)->{String secret=code.getText().toString().replaceAll("[\\s-]","").toUpperCase(Locale.US);if(!secret.matches("[A-Z2-7]{16}")){message("Нужен код из 16 букв и цифр");return;}status.setText("Подключение…");new Thread(()->{HttpsURLConnection c=null;try{PinnedTrust trust=new PinnedTrust(null);c=connection(target,"/api/pair",trust);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.connect();if(trust.observed==null)throw new Exception("Не удалось проверить станцию");String challenge=nonce();JSONObject q=new JSONObject();q.put("nonce",challenge);q.put("name",Build.MANUFACTURER+" "+Build.MODEL);q.put("proof",mac(secret,challenge+"|"+trust.observed));try(OutputStream out=c.getOutputStream()){out.write(q.toString().getBytes("UTF-8"));}int result=c.getResponseCode();JSONObject reply=new JSONObject(new String(readBounded(result<400?c.getInputStream():c.getErrorStream(),8192),"UTF-8"));if(result!=200)throw new Exception(reply.optString("error","Код не подошёл"));String value=reply.getString("token"),expected=mac(secret,challenge+"|"+trust.observed+"|"+value);if(!MessageDigest.isEqual(expected.getBytes("US-ASCII"),reply.getString("proof").getBytes("US-ASCII")))throw new Exception("Подтверждение станции не совпало");JSONObject record=new JSONObject();record.put("host",target);record.put("pin",trust.observed);record.put("token",value);record.put("clientId",reply.getString("clientId"));store.save(record.toString());host=target;pin=trust.observed;key=value;clientId=reply.getString("clientId");runOnUiThread(()->openPanel());}catch(Exception e){message(e.getMessage());runOnUiThread(()->status.setText("Не удалось подключить"));}finally{if(c!=null)c.disconnect();}},"station-pairing").start();}).setNegativeButton("Отмена",null).show();}
 private void connectKnown(){if(destroyed||!reconnecting.compareAndSet(false,true))return;status.setText("Проверяем станцию…");new Thread(()->{try{request("/api/status",null);runOnUiThread(()->openPanel());}catch(Exception e){String relocated=findKnownAddress();if(relocated!=null){host=relocated;runOnUiThread(()->openPanel());return;}runOnUiThread(()->{introductory("Станция недоступна","Проверьте, что телефон подключён к той же сети Wi-Fi. Если адрес станции изменился, укажите новый адрес: сохранённый сертификат проверит её подлинность.");LinearLayout page=(LinearLayout)content.getTag();page.addView(button("Повторить",()->connectKnown()));page.addView(button("Изменить адрес",()->changeKnownAddress()));page.addView(button("Другая станция",()->discover()));status.setText("Нет связи");});}finally{reconnecting.set(false);}},"station-connect").start();}
 private String findKnownAddress(){if(pin==null||key==null)return null;try(DatagramSocket socket=new DatagramSocket()){socket.setBroadcast(true);socket.setSoTimeout(550);byte[] query=("STATION_STUDIO_DISCOVER_V1:"+nonce()).getBytes("US-ASCII");Set<String> destinations=new HashSet<>();destinations.add("255.255.255.255");Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();while(interfaces.hasMoreElements())for(InterfaceAddress a:interfaces.nextElement().getInterfaceAddresses())if(a.getBroadcast()!=null)destinations.add(a.getBroadcast().getHostAddress());for(String address:destinations)socket.send(new DatagramPacket(query,query.length,InetAddress.getByName(address),8788));long until=System.currentTimeMillis()+4500;Set<String> tried=new HashSet<>();while(System.currentTimeMillis()<until&&!destroyed){try{byte[] b=new byte[4096];DatagramPacket reply=new DatagramPacket(b,b.length);socket.receive(reply);String candidate=localHost(reply.getAddress().getHostAddress());JSONObject descriptor=new JSONObject(new String(b,0,reply.getLength(),"UTF-8"));if(descriptor.optInt("tlsPort")!=8789||!tried.add(candidate))continue;HttpsURLConnection c=connection(candidate,"/api/status",new PinnedTrust(pin));try{c.setConnectTimeout(900);c.setReadTimeout(2500);c.setRequestProperty("Authorization","Bearer "+key);if(c.getResponseCode()==200)return candidate;}finally{c.disconnect();}}catch(Exception ignored){}}}catch(Exception ignored){}return null;}
 private void changeKnownAddress(){EditText f=new EditText(this);f.setText(host);new AlertDialog.Builder(this).setTitle("Новый адрес той же станции").setView(f).setPositiveButton("Проверить",(d,w)->{try{host=localHost(f.getText().toString());connectKnown();}catch(Exception e){message(e.getMessage());}}).setNegativeButton("Отмена",null).show();}
 private void openPanel(){if(destroyed)return;if(topBar!=null)topBar.setVisibility(View.GONE);discoveryGeneration.incrementAndGet();try{JSONObject record=new JSONObject();record.put("host",host);record.put("pin",pin);record.put("token",key);record.put("clientId",clientId);store.save(record.toString());}catch(Exception ignored){}connected=true;status.setText("AliceKit · на связи");content.removeAllViews();if(web!=null)web.destroy();web=new WebView(this);web.setBackgroundColor(0xfffaf9fd);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setCacheMode(WebSettings.LOAD_NO_CACHE);web.clearCache(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);String origin="https://"+host+":8789";
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,String url){if(url.startsWith(origin+"/"))return false;if(url.equals("https://station-studio-community.shaaaape.chatgpt.site")||url.startsWith("https://station-studio-community.shaaaape.chatgpt.site/")||url.startsWith("https://oauth.yandex.ru/")||url.startsWith("https://github.com/golodgolub-bit/Station-Studio")){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){message("Не удалось открыть браузер");}}return true;}@Override public void onPageFinished(WebView v,String url){if(url.startsWith(origin+"/"))v.evaluateJavascript("if(window.stationNativeConnect)window.stationNativeConnect("+JSONObject.quote(key)+");",null);}@Override public void onReceivedSslError(WebView v,SslErrorHandler handler,SslError error){try{if(!error.getUrl().startsWith(origin+"/")||error.hasError(SslError.SSL_EXPIRED)||error.hasError(SslError.SSL_NOTYETVALID))throw new Exception();Bundle state=SslCertificate.saveState(error.getCertificate());byte[] der=state.getByteArray("x509-certificate");String actual=hex(MessageDigest.getInstance("SHA-256").digest(der));if(!MessageDigest.isEqual(actual.getBytes("US-ASCII"),pin.getBytes("US-ASCII")))throw new Exception();((X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(der))).checkValidity();handler.proceed();}catch(Exception e){handler.cancel();message("Сертификат станции изменился. Подключитесь заново по коду.");}}});
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=c;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(i,81);}catch(Exception e){files.onReceiveValue(null);files=null;message("Выбор файла недоступен");}return true;}@Override public boolean onJsConfirm(WebView v,String u,String text,JsResult r){new AlertDialog.Builder(ControllerActivity.this).setMessage(text).setPositiveButton("Продолжить",(d,w)->r.confirm()).setNegativeButton("Отмена",(d,w)->r.cancel()).setOnCancelListener(d->r.cancel()).show();return true;}@Override public boolean onJsAlert(WebView v,String u,String text,JsResult r){new AlertDialog.Builder(ControllerActivity.this).setMessage(text).setPositiveButton("Хорошо",(d,w)->r.confirm()).show();return true;}});
  web.addJavascriptInterface(new Object(){@JavascriptInterface public void connectYandexHome(){runOnUiThread(()->startActivity(new Intent(ControllerActivity.this,YandexHomeActivity.class)));}@JavascriptInterface public void openCommunity(){runOnUiThread(()->startActivity(new Intent(ControllerActivity.this,CommunityActivity.class)));}@JavascriptInterface public void checkUpdates(){runOnUiThread(()->checkUpdate());}@JavascriptInterface public void connectionSettings(){runOnUiThread(()->connectionMenu());}@JavascriptInterface public void reconnect(){runOnUiThread(()->connectKnown());}@JavascriptInterface public void saveMatrix(String value){if(value==null||value.length()>131072)return;try{if(!"station-studio-matrix-v1".equals(new JSONObject(value).optString("format")))return;}catch(Exception e){return;}drawing=value;runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"station-animation.json");startActivityForResult(i,82);});}},"StationStudio");content.addView(web,new LinearLayout.LayoutParams(-1,-1));web.loadUrl(origin+"/?controller=2");
 }
 private void connectionMenu(){new AlertDialog.Builder(this).setTitle("Подключение").setMessage(host==null?"Станция не выбрана":"Станция: "+host).setPositiveButton("Найти станции",(d,w)->discover()).setNeutralButton("Забыть подключение",(d,w)->{if(store!=null)store.clear();host=null;key=null;pin=null;connected=false;discover();}).setNegativeButton("Закрыть",null).show();}
 private void checkLocalUpdate(){if(key==null){message("Сначала подключите станцию");return;}status.setText("Проверяем обновление…");new Thread(()->{try{JSONObject info=request("/api/update",null);PackageInfo own=getPackageManager().getPackageInfo(getPackageName(),PackageManager.GET_SIGNATURES);if(info.getInt("versionCode")<=own.versionCode){message("Установлена последняя размещённая версия");return;}if(info.getLong("size")>64*1024*1024)throw new Exception("Слишком большой файл обновления");HttpsURLConnection c=connection(host,"/api/update/controller.apk",new PinnedTrust(pin));c.setRequestProperty("Authorization","Bearer "+key);byte[] bytes;try{if(c.getResponseCode()!=200)throw new Exception("Обновление недоступно");bytes=readBounded(c.getInputStream(),64*1024*1024);}finally{c.disconnect();}if(bytes.length!=info.getLong("size")||!hex(MessageDigest.getInstance("SHA-256").digest(bytes)).equals(info.getString("sha256")))throw new Exception("Контрольная сумма не совпала");File file=new File(getCacheDir(),"studio-update.apk");try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}PackageInfo next=getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),PackageManager.GET_SIGNATURES);if(next==null||!next.packageName.equals(getPackageName())||next.versionCode<=own.versionCode||own.signatures.length!=1||next.signatures.length!=1||!MessageDigest.isEqual(own.signatures[0].toByteArray(),next.signatures[0].toByteArray())){file.delete();throw new Exception("Подпись или пакет обновления не совпал");}runOnUiThread(()->{if(Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(this).setMessage("Android запросит разрешение устанавливать обновления AliceKit. После разрешения нажмите «Обновить» ещё раз.").setPositiveButton("Открыть настройки",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())))).setNegativeButton("Отмена",null).show();return;}Intent install=new Intent(Intent.ACTION_VIEW);install.setDataAndType(Uri.parse("content://"+getPackageName()+".updates/update.apk"),"application/vnd.android.package-archive");install.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(install);});}catch(Exception e){message(e.getMessage());}finally{runOnUiThread(()->status.setText(connected?"AliceKit · на связи":"AliceKit"));}},"station-app-update").start();}

 private void launchPublicInstall(){if(Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){pendingPublicInstall=true;new AlertDialog.Builder(this).setTitle("Установка обновления").setMessage("Разрешите Android устанавливать обновления AliceKit. После возврата установка продолжится автоматически.").setPositiveButton("Разрешить",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())))).setNegativeButton("Отмена",(d,w)->pendingPublicInstall=false).show();return;}pendingPublicInstall=false;PublicUpdates.install(this);}
 private void checkUpdate(){if(!updating.compareAndSet(false,true))return;message("Проверяем общий канал обновлений…");new Thread(()->{try{JSONObject info=PublicUpdates.manifest();File file=PublicUpdates.download(this,info);runOnUiThread(()->{if(file==null){message("Установлена актуальная версия");return;}new AlertDialog.Builder(this).setTitle("AliceKit "+info.optString("versionName")).setMessage(info.optString("notes","Готово обновление приложения")).setPositiveButton("Установить",(d,w)->launchPublicInstall()).setNegativeButton("Позже",null).show();});}catch(Exception e){runOnUiThread(()->{AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle("Обновления").setMessage(e.getMessage()+". Для общего канала достаточно интернета; подключение к станции не требуется.").setNegativeButton("Закрыть",null);if(key!=null&&connected)dialog.setPositiveButton("Локальный выпуск",(d,w)->checkLocalUpdate());dialog.show();});}finally{updating.set(false);}},"public-update").start();}
 @Override protected void onResume(){super.onResume();if(pendingPublicInstall&&(Build.VERSION.SDK_INT<26||getPackageManager().canRequestPackageInstalls()))launchPublicInstall();}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==92&&result==RESULT_OK&&data!=null){try{pair(localHost(data.getStringExtra("host")));}catch(Exception e){message(e.getMessage());}}if(code==81&&files!=null){files.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null?new Uri[]{data.getData()}:null);files=null;}if(code==82){String value=drawing;drawing=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&value!=null)try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(value.getBytes("UTF-8"));message("Анимация сохранена");}catch(Exception e){message("Не удалось сохранить файл");}}}
 @Override public void onBackPressed(){if(web!=null&&connected)web.evaluateJavascript("document.querySelector('#overview').classList.contains('active')",value->{if("true".equals(value))finish();else web.evaluateJavascript("showTab('overview')",null);});else super.onBackPressed();}
 @Override public void onDestroy(){destroyed=true;discoveryGeneration.incrementAndGet();if(files!=null)files.onReceiveValue(null);if(callback!=null)connectivity.unregisterNetworkCallback(callback);if(web!=null)web.destroy();super.onDestroy();}
